function V3Film(){
 const filmRef=React.useRef(null),[needsSound,setNeedsSound]=useState(false);
 const playWithSound=()=>{const video=filmRef.current;if(!video)return;video.muted=false;video.volume=1;video.play().then(()=>setNeedsSound(false)).catch(()=>setNeedsSound(true))};
 useEffect(()=>{
  const video=filmRef.current;if(!video)return;
  let inView=false,disposed=false;
  const sync=()=>{
   if(inView&&!document.hidden){
    if(video.ended)video.currentTime=0;
    const playing=video.play();
    if(playing)playing.then(()=>{if(disposed||!inView||document.hidden)video.pause();else setNeedsSound(video.muted||video.volume===0)}).catch(error=>{if(!disposed&&inView&&error.name==='NotAllowedError')setNeedsSound(true)});
   }else video.pause();
  };
  const observer=new IntersectionObserver(([entry])=>{inView=entry.isIntersecting&&entry.intersectionRatio>=.35;sync()},{threshold:[0,.35]});
  observer.observe(video);document.addEventListener('visibilitychange',sync);
  return()=>{disposed=true;observer.disconnect();document.removeEventListener('visibilitychange',sync);video.pause()};
 },[]);
 return <section id="founder-film" className="v3-wrap v4-section v4-film" style={{scrollMarginTop:110}}><div className="v4-film-panel"><div className="v4-film-copy"><h2>Your buyer has changed.<em>Has your marketing?</em></h2><p>Before a buyer speaks to your sales team, they have already compared projects on Instagram, Google and WhatsApp. We meet them there, answer their questions and hand your team a buyer who is ready to visit.</p><ul className="v4-film-points"><li><strong>Research first.</strong> Every campaign starts with your buyer, catchment and competitors.</li><li><strong>Creative at volume.</strong> Fresh ads tested every week, not one poster a month.</li><li><strong>Follow-up built in.</strong> WhatsApp and CRM routing so no enquiry goes cold.</li></ul><div className="v3-actions"><V3Button>Get a free marketing plan</V3Button><V3Button href={v3link('about')} outline>Meet the founders</V3Button></div></div><div className="v3-video-frame"><video ref={filmRef} onVolumeChange={()=>{const video=filmRef.current;if(video)setNeedsSound(video.muted||video.volume===0)}} controls playsInline preload="metadata" poster="assets/qd-ad-enhanced-cover.jpg" src="assets/qd-ad-enhanced-1080x1920.mp4" aria-label="Adarsh: your buyer has changed"/>{needsSound&&<button type="button" className="v3-film-sound" onClick={playWithSound}>▶ Play with sound</button>}<div className="v3-video-label">Adarsh Jee Pandey · CEO &amp; co-founder<br/><strong>A better start for your sales team.</strong></div></div></div></section>}
