function V3CaseCard({p,d}){return <a className="v3-case-card" href={'case-'+p.slug+'.html'}><div className="case-art"><img src={'shots/'+(p.image||d[2])} alt={p.developer+' website imagery'} loading="lazy"/><span className="case-logo"><img src={'brands/'+d[1]} alt={p.developer}/></span><span className="case-open" aria-hidden="true">↗</span><span className="case-image-note">Developer imagery</span></div><div className="case-copy"><span className="v3-eyebrow">{p.project}</span><h3>{p.hook}</h3><div className="case-number"><strong>{p.metric}</strong><span>{p.metricLabel}</span></div><p>{p.subtitle}</p><div className="case-bottom"><span>{p.type}</span><b>Read case study ↗</b></div></div></a>}
